import fs from 'fs/promises';
import path from 'path';
import { createHash, randomUUID } from 'crypto';
import {
  ProfileContextSchema,
  type ProfileContext,
} from '../../types/design-profile';
import { errnoCode } from '../../utils/errnoCode';

interface ContextLocation {
  directory: string;
  requestId: string;
}

export class ProfileContextConflict extends Error {}

const contextFile = ({ directory, requestId }: ContextLocation): string =>
  path.join(
    directory,
    'requests',
    createHash('sha256').update(requestId).digest('hex'),
    'context.json',
  );

export const readProfileContext = async (
  location: ContextLocation,
): Promise<ProfileContext | null> => {
  try {
    const context = ProfileContextSchema.parse(
      JSON.parse(await fs.readFile(contextFile(location), 'utf8')),
    );
    if (context.requestId !== location.requestId)
      throw new Error('Profile context receipt identity does not match');
    return context;
  } catch (error) {
    if (errnoCode(error) === 'ENOENT') return null;
    throw error;
  }
};

export const writeProfileContext = async ({
  directory,
  context,
}: {
  directory: string;
  context: ProfileContext;
}): Promise<ProfileContext> => {
  const validated = ProfileContextSchema.parse(context);
  const location = { directory, requestId: validated.requestId };
  const filename = contextFile(location);
  await fs.mkdir(path.dirname(filename), { recursive: true, mode: 0o700 });
  const staging = `${filename}.${randomUUID()}.partial`;
  await fs.writeFile(staging, JSON.stringify(validated), { mode: 0o600 });
  try {
    await fs.link(staging, filename);
  } catch (error) {
    if (errnoCode(error) !== 'EEXIST') throw error;
    if (
      JSON.stringify(await readProfileContext(location)) !==
      JSON.stringify(validated)
    )
      throw new ProfileContextConflict(
        'A different context receipt already exists for this request',
      );
  } finally {
    await fs.unlink(staging);
  }
  return validated;
};
